16	/// Complete the given command, shell-agnostic
17	pub fn complete(
18	    cmd: &mut clap::Command,
19	    args: Vec<OsString>,
20	    arg_index: usize,
21	    current_dir: Option<&std::path::Path>,
22	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
23	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
24	    cmd.build();
25	
26	    let raw_args = clap_lex::RawArgs::new(args);
27	    let mut cursor = raw_args.cursor();
28	    let mut target_cursor = raw_args.cursor();
29	    raw_args.seek(
30	        &mut target_cursor,
31	        clap_lex::SeekFrom::Start(arg_index as u64),
32	    );
33	    // As we loop, `cursor` will always be pointing to the next item
34	    raw_args.next_os(&mut target_cursor);
35	    debug!("complete: target_cursor={target_cursor:?}");
36	
37	    // TODO: Multicall support
38	    if !cmd.is_no_binary_name_set() {
39	        raw_args.next_os(&mut cursor);
40	    }
41	
42	    let mut current_cmd = &*cmd;
43	    let mut pos_index = 1;
44	    let mut is_escaped = false;
45	    let mut next_state = ParseState::ValueDone;
46	    // Set when an already closed word carried a value that cannot be part of
47	    // the command line (a delimiter-separated value set that is overfull, has
48	    // an empty segment, ...). Completion then reports "no completion generated"
49	    // instead of guessing at unrelated candidates.
50	    let mut is_illegal = false;
51	    // Ids of options explicitly present in `args[..arg_index]`, used to hide
52	    // conflicting candidates. Only recognized option names are recorded;
53	    // values, positionals, `--`-escaped words, default values and env values
54	    // never are.
55	    let mut explicit_opts = HashSet::<Id>::new();
56	    while let Some(arg) = raw_args.next(&mut cursor) {
57	        let current_state = next_state;
58	        next_state = ParseState::ValueDone;
59	        debug!(
60	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
61	            arg.to_value_os(),
62	        );
63	        if cursor == target_cursor {
64	            if is_illegal {
65	                return Err(std::io::Error::other("no completion generated"));
66	            }
67	            let disabled = gather_disabled_args(current_cmd, &explicit_opts);
68	            return complete_arg(
69	                &arg,
70	                current_cmd,
71	                current_dir,
72	                pos_index,
73	                is_escaped,
74	                current_state,
75	                &disabled,
76	            );
77	        }
78	
79	        if let Ok(value) = arg.to_value() {
80	            // A dangling delimiter forces this word to be the option's next
81	            // segment, never a subcommand.
82	            let open_segment = matches!(&current_state, ParseState::Opt(state) if state.open);
83	            if !open_segment {
84	                if let Some(next_cmd) = current_cmd.find_subcommand(value) {
85	                    current_cmd = next_cmd;
86	                    pos_index = 1;
87	                    continue;
88	                }
89	            }
90	        }
91	
92	        // While a dangling delimiter makes the next segment mandatory
93	        // (`--opt=a,`), a closed word may only be that segment.  An option
94	        // word (recognized or not) or `--` cannot fill it and clap rejects the
95	        // line, so completion reports an error instead of guessing a stop or a
96	        // new option. An option with `allow_hyphen_values` still accepts a
97	        // hyphen-prefixed word as the segment. A plain value word below is
98	        // consumed as the segment.
99	        if let ParseState::Opt(state) = &current_state {
100	            if state.open && !is_escaped && !opt_allows_hyphen(&current_state, &arg) {
101	                let is_option_word = arg.is_escape()
102	                    || arg.to_long().is_some()
103	                    || arg
104	                        .to_short()
105	                        .is_some_and(|short| !short.is_negative_number());
106	                if is_option_word {
107	                    is_illegal = true;
108	                }
109	            }
110	        }
111	
112	        if is_escaped {
113	            (next_state, pos_index) =
114	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
115	        } else if arg.is_escape() {
116	            is_escaped = true;
117	        } else if opt_allows_hyphen(&current_state, &arg) {
118	            match current_state {
119	                ParseState::Opt(state) => {
120	                    next_state = advance_opt_value(state, arg.to_value_os(), &mut is_illegal);
121	                }
122	                _ => unreachable!("else branch is only reachable in Opt state"),
123	            }
124	        } else if let Some((flag, value)) = arg.to_long() {
125	            if let Ok(flag) = flag {
126	                let opt = current_cmd.get_arguments().find(|a| {
127	                    let longs = a.get_long_and_visible_aliases();
128	                    let is_find = longs.map(|v| {
129	                        let mut iter = v.into_iter();
130	                        let s = iter.find(|s| *s == flag);
131	                        s.is_some()
132	                    });
133	                    is_find.unwrap_or(false)
134	                });
135	
136	                if let Some(opt) = opt {
137	                    explicit_opts.insert(opt.get_id().clone());
138	                    if opt.get_num_args().expect("built").takes_values() {
139	                        match value {
140	                            // A bare `--name` still expects its value as the next word.
141	                            None => next_state = ParseState::Opt(OptState::new(opt, 1)),
142	                            // A closed `--name=value` word normally ends the
143	                            // occurrence, but a dangling value delimiter with
144	                            // room for another segment keeps accepting values.
145	                            Some(value) => {
146	                                next_state = attached_opt_state(opt, value, &mut is_illegal);
147	                            }
148	                        }
149	                    }
150	                } else if pos_allows_hyphen(current_cmd, pos_index) {
151	                    (next_state, pos_index) =
152	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
153	                }
154	            }
155	        } else if let Some(short) = arg.to_short() {
156	            let (leading_flags, takes_value_opt, mut short, cluster_valid) =
157	                parse_shortflags(current_cmd, short);
158	            // Only a cluster made entirely of recognized flags records state.
159	            // Splitting an invalid short string into known and unknown members
160	            // would be guesswork and could suppress conflicting candidates, so
161	            // invalid clusters keep the existing completion behavior; clap's
162	            // parser would reject them anyway.
163	            if cluster_valid {
164	                // Every recognized flag in the cluster was explicitly supplied.
165	                for flag in leading_flags.chars() {
166	                    if let Some(opt) = current_cmd.get_arguments().find(|a| {
167	                        a.get_short_and_visible_aliases()
168	                            .is_some_and(|shorts| shorts.contains(&flag))
169	                    }) {
170	                        explicit_opts.insert(opt.get_id().clone());
171	                    }
172	                }
173	            }
174	            if let Some(opt) = takes_value_opt {
175	                if let Some(remainder) = short.next_value_os() {
176	                    // A closed `-ovalue` / `-o=value` word; advance like the
177	                    // long `--opt=value` form.
178	                    let value = remainder.strip_prefix("=").unwrap_or(remainder);
179	                    next_state = attached_opt_state(opt, value, &mut is_illegal);
180	                } else {
181	                    next_state = ParseState::Opt(OptState::new(opt, 1));
182	                }
183	            } else if pos_allows_hyphen(current_cmd, pos_index) {
184	                (next_state, pos_index) =
185	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
186	            }
187	        } else {
188	            match current_state {
189	                ParseState::ValueDone | ParseState::Pos(..) => {
190	                    (next_state, pos_index) =
191	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
192	                }
193	                ParseState::Opt(state) => {
194	                    next_state = advance_opt_value(state, arg.to_value_os(), &mut is_illegal);
195	                }
196	            }
197	        }
198	    }
199	
200	    Err(std::io::Error::other("no completion generated"))
201	}
202	
203	#[derive(Debug, PartialEq, Eq, Clone)]
204	enum ParseState<'a> {
205	    /// Parsing a value done, there is no state to record.
206	    ValueDone,
207	
208	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
209	    Pos((usize, usize)),
210	
211	    /// Parsing a optional flag argument
212	    Opt(OptState<'a>),
213	}
214	
215	/// Ongoing state while an option still accepts value words.
216	#[derive(Debug, PartialEq, Eq, Clone)]
217	struct OptState<'a> {
218	    opt: &'a clap::Arg,
219	    /// Ordinal of the value word about to be consumed within this occurrence.
220	    /// A bare `--name` waiting for its first value starts at `1`; this is the
221	    /// value handed to [`ArgValueCompleter::complete_at`] as `arg_index + 1`,
222	    /// so it counts shell words and is unaffected by the value delimiter.
223	    word: usize,
224	    /// Delimiter segments already closed by earlier value words, in order.
225	    used: Vec<OsString>,
226	    /// The state was reached through a dangling value delimiter, so the next
227	    /// word is another segment of this option rather than an optional stop.
228	    open: bool,
229	}
230	
231	impl<'a> OptState<'a> {
232	    fn new(opt: &'a clap::Arg, word: usize) -> Self {
233	        Self {
234	            opt,
235	            word,
236	            used: Vec::new(),
237	            open: false,
238	        }
239	    }
240	}
241	
242	/// Whether an option carries several values split by a delimiter inside one
243	/// shell word *and* bounds how many such values it accepts.
244	///
245	/// An argument with the default range of one value may still pack an arbitrary
246	/// number of delimiter segments into its single word (clap's parser allows it),
247	/// and completion preserves that legacy behavior; only multi-value arguments
248	/// count segments against their range.
249	fn is_bounded_delimited(opt: &clap::Arg) -> Option<char> {
250	    let delim = opt.get_value_delimiter()?;
251	    if opt.get_num_args().expect("built").max_values() > 1 {
252	        Some(delim)
253	    } else {
254	        None
255	    }
256	}
257	
258	/// Split a shell value on its delimiter into its closed segments.
259	///
260	/// Returns `(segments, dangling)` where `dangling` is set when the value ends
261	/// with the delimiter: the final empty piece is the segment still being typed
262	/// rather than a closed (empty and therefore invalid) segment. Splitting works
263	/// on raw [`OsStr`] bytes, so invalid UTF-8 values are handled too.
264	fn split_delimited(value: &OsStr, delim: char) -> (Vec<&OsStr>, bool) {
265	    let mut buf = [0_u8; 4];
266	    let delim_str = delim.encode_utf8(&mut buf);
267	    let mut segments: Vec<&OsStr> = value.split(delim_str).collect();
268	    let dangling = value.contains(delim_str) && segments.last().is_some_and(|last| last.is_empty());
269	    if dangling {
270	        segments.pop();
271	    }
272	    (segments, dangling)
273	}
274	
275	/// Fold one closed value word into an option's ongoing value state.
276	///
277	/// `Ok(None)` means the occurrence is complete, `Ok(Some(state))` that another
278	/// value word is accepted and `Err(())` that the word cannot be part of a valid
279	/// command line (an empty delimiter segment or more segments than the option
280	/// accepts); the latter produces "no completion generated" rather than guesses.
281	fn consume_opt_word<'a>(
282	    prior: OptState<'a>,
283	    value: &OsStr,
284	    attached: bool,
285	) -> Result<Option<OptState<'a>>, ()> {
286	    let opt = prior.opt;
287	    let range = opt.get_num_args().expect("built");
288	    let max = range.max_values();
289	    let ordinal = prior.word;
290	    let mut used = prior.used;
291	
292	    let Some(delim) = is_bounded_delimited(opt) else {
293	        // Legacy behavior: count whole shell words against the range; whatever
294	        // is packed behind a delimiter does not extend or shorten the count.
295	        // An attached value always closes the occurrence.
296	        return Ok(if !attached && ordinal < max {
297	            Some(OptState {
298	                opt,
299	                word: ordinal + 1,
300	                used,
301	                open: false,
302	            })
303	        } else {
304	            None
305	        });
306	    };
307	
308	    let mut buf = [0_u8; 4];
309	    let delim_str = delim.encode_utf8(&mut buf);
310	    let (segments, dangling) = split_delimited(value, delim);
311	    // Empty pieces are only invalid once a delimiter actually separates
312	    // segments; a bare empty value (`--opt=`) keeps its old tolerant behavior.
313	    if value.contains(delim_str) && segments.iter().any(|s| s.is_empty()) {
314	        return Err(());
315	    }
316	    // A closed segment must name a value the option accepts; an unknown value
317	    // cannot be part of a valid command line.
318	    if !segments_are_known(opt, &segments) {
319	        return Err(());
320	    }
321	    let closed = used.len() + segments.len();
322	    if closed > max || (closed == max && dangling) {
323	        return Err(());
324	    }
325	    used.extend(segments.iter().map(|s| s.to_os_string()));
326	
327	    // An attached value closes the occurrence unless a dangling delimiter
328	    // still accepts another segment; a space-separated word keeps accepting
329	    // values until the range is full.
330	    let accepts_more = dangling || (!attached && closed < max);
331	    Ok(if accepts_more {
332	        Some(OptState {
333	            opt,
334	            word: ordinal + 1,
335	            used,
336	            open: dangling,
337	        })
338	    } else {
339	        None
340	    })
341	}
342	
343	/// State after a closed `--opt=value` word: `ValueDone` when the occurrence is
344	/// complete, `Opt` when a dangling delimiter still accepts another segment.
345	/// Illegal values flag the whole command line as uncompletable.
346	fn attached_opt_state<'a>(
347	    opt: &'a clap::Arg,
348	    value: &OsStr,
349	    is_illegal: &mut bool,
350	) -> ParseState<'a> {
351	    match consume_opt_word(OptState::new(opt, 1), value, true) {
352	        Ok(Some(state)) => ParseState::Opt(state),
353	        Ok(None) => ParseState::ValueDone,
354	        Err(()) => {
355	            *is_illegal = true;
356	            ParseState::ValueDone
357	        }
358	    }
359	}
360	
361	/// Advance an ongoing option occurrence by one space-separated value word.
362	fn advance_opt_value<'a>(
363	    state: OptState<'a>,
364	    value: &OsStr,
365	    is_illegal: &mut bool,
366	) -> ParseState<'a> {
367	    match consume_opt_word(state, value, false) {
368	        Ok(Some(next)) => ParseState::Opt(next),
369	        Ok(None) => ParseState::ValueDone,
370	        Err(()) => {
371	            *is_illegal = true;
372	            ParseState::ValueDone
373	        }
374	    }
375	}
376	
377	/// Result of analyzing the value word under the cursor for an option that
378	/// packs delimiter-separated values.
379	struct DelimCursor<'s> {
380	    /// Text of the segment currently being typed.
381	    current: &'s OsStr,
382	    /// Closed segments that precede it, in order.
383	    closed: Vec<&'s OsStr>,
384	    /// Everything in this shell word before the current segment, including the
385	    /// trailing delimiter, to re-prefix candidates with.
386	    prefix: &'s str,
387	}
388	
389	/// Whether every closed delimiter segment names a value the option accepts.
390	///
391	/// Options without a fixed value set accept anything.  A bare empty value
392	/// (`--opt=`) keeps its legacy tolerant treatment; empty segments separated
393	/// by a delimiter are rejected before this point.  A segment that is not
394	/// valid UTF-8 cannot match a possible value and is rejected, as clap's
395	/// parser would reject it.
396	fn segments_are_known(opt: &clap::Arg, segments: &[&OsStr]) -> bool {
397	    let Some(possible) = possible_values(opt) else {
398	        return true;
399	    };
400	    let ignore_case = opt.is_ignore_case_set();
401	    let possible: Vec<_> = possible.collect();
402	    segments.iter().all(|segment| {
403	        segment
404	            .to_str()
405	            .is_some_and(|s| s.is_empty() || possible.iter().any(|pv| pv.matches(s, ignore_case)))
406	    })
407	}
408	
409	/// Split the cursor value of a bounded delimiter option into the segment being
410	/// edited and its already closed prefix segments.
411	///
412	/// `Ok(None)` means the option is not a bounded delimiter option (legacy
413	/// completion applies); `Err(())` means the cursor sits at an illegal segment
414	/// position (a leading/empty segment or one past the accepted number of
415	/// values), which must not produce candidates.
416	fn cursor_delimited<'s>(
417	    opt: &clap::Arg,
418	    value: &'s OsStr,
419	    prior_segments: usize,
420	) -> Result<Option<DelimCursor<'s>>, ()> {
421	    let Some(delim) = is_bounded_delimited(opt) else {
422	        return Ok(None);
423	    };
424	    let max = opt.get_num_args().expect("built").max_values();
425	    // The cursor word being edited keeps the legacy whole-word completion when
426	    // it is not valid UTF-8; earlier closed words are still tracked by bytes.
427	    let value_str = match value.to_str() {
428	        Some(s) => s,
429	        None => return Ok(None),
430	    };
431	    let mut buf = [0_u8; 4];
432	    let delim_str = delim.encode_utf8(&mut buf);
433	
434	    let Some(pos) = value_str.rfind(delim) else {
435	        return Ok(Some(DelimCursor {
436	            current: value,
437	            closed: Vec::new(),
438	            prefix: "",
439	        }));
440	    };
441	    let (prefix, current) = value_str.split_at(pos + delim.len_utf8());
442	    let closed: Vec<&OsStr> = prefix[..prefix.len() - delim_str.len()]
443	        .split(delim)
444	        .map(OsStr::new)
445	        .collect();
446	    if closed.iter().any(|s| s.is_empty())
447	        || prior_segments + closed.len() >= max
448	        || !segments_are_known(opt, &closed)
449	    {
450	        return Err(());
451	    }
452	    Ok(Some(DelimCursor {
453	        current: OsStr::new(current),
454	        closed,
455	        prefix,
456	    }))
457	}
458	
459	fn complete_arg(
460	    arg: &clap_lex::ParsedArg<'_>,
461	    cmd: &clap::Command,
462	    current_dir: Option<&std::path::Path>,
463	    pos_index: usize,
464	    is_escaped: bool,
465	    state: ParseState<'_>,
466	    disabled: &HashSet<Id>,
467	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
468	    debug!(
469	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
470	        arg,
471	        cmd.get_name(),
472	        current_dir,
473	        pos_index,
474	        state
475	    );
476	    let mut completions = Vec::<CompletionCandidate>::new();
477	
478	    match state {
479	        ParseState::ValueDone => {
480	            // A closed `--name=value` word (or a short cluster carrying an
481	            // inline value, e.g. `-ovalue` / `-o=value`) is the option's value
482	            // position: only the option's own values are completed, exactly as
483	            // if the value had been written as a separate word.  The content
484	            // after `=` never takes part in subcommand, positional or
485	            // option-name completion, and the word itself is not yet part of
486	            // the conflict set.
487	            if !is_escaped {
488	                if let Some(values) = complete_inline_option_value(arg, cmd, current_dir, disabled)
489	                {
490	                    let values =
491	                        values.map_err(|()| std::io::Error::other("no completion generated"))?;
492	                    completions.extend(values);
493	                    return finalize_completions(completions);
494	                }
495	            }
496	
497	            // After `--`, only positional arguments are completed.
498	            if !is_escaped {
499	                if let Ok(value) = arg.to_value() {
500	                    completions.extend(complete_subcommand(value, cmd));
501	                }
502	            }
503	
504	            if let Some(positional) = cmd
505	                .get_positionals()
506	                .find(|p| p.get_index() == Some(pos_index))
507	            {
508	                if !disabled.contains(positional.get_id()) {
509	                    completions.extend(complete_arg_value(
510	                        arg.to_value(),
511	                        positional,
512	                        current_dir,
513	                        0,
514	                    ));
515	                }
516	            }
517	            if !is_escaped {
518	                completions.extend(complete_option(arg, cmd, current_dir, disabled));
519	            }
520	        }
521	        ParseState::Pos((_, num_arg)) => {
522	            if let Some(positional) = cmd
523	                .get_positionals()
524	                .find(|p| p.get_index() == Some(pos_index))
525	            {
526	                if !disabled.contains(positional.get_id()) {
527	                    completions.extend(complete_arg_value(
528	                        arg.to_value(),
529	                        positional,
530	                        current_dir,
531	                        num_arg.saturating_sub(1),
532	                    ));
533	                }
534	                if !is_escaped
535	                    && positional
536	                        .get_num_args()
537	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
538	                {
539	                    completions.extend(complete_option(arg, cmd, current_dir, disabled));
540	                }
541	            }
542	        }
543	        ParseState::Opt(state) => {
544	            let opt = state.opt;
545	            if !disabled.contains(opt.get_id()) {
546	                match complete_separate_opt_value(arg.to_value(), &state, current_dir) {
547	                    Ok(values) => completions.extend(values),
548	                    // The cursor sits at an illegal segment position (an empty
549	                    // segment or one past the accepted number of values).
550	                    Err(()) => return Err(std::io::Error::other("no completion generated")),
551	                }
552	            }
553	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
554	            if state.word > min && !state.open {
555	                // Also complete this raw_arg as a positional argument, flags,
556	                // options and subcommand.  A dangling delimiter (`state.open`)
557	                // requires the next word to be this option's segment: it cannot
558	                // be a valid stop, so nothing else is offered there.
559	                completions.extend(complete_arg(
560	                    arg,
561	                    cmd,
562	                    current_dir,
563	                    pos_index,
564	                    is_escaped,
565	                    ParseState::ValueDone,
566	                    disabled,
567	                )?);
568	            }
569	        }
570	    }
571	
572	    finalize_completions(completions)
573	}
574	
575	/// Hide hidden candidates when visible ones exist, deduplicate by id and sort
576	/// into the presentation order shared by every completion source.
577	fn finalize_completions(
578	    mut completions: Vec<CompletionCandidate>,
579	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
580	    if completions.iter().any(|a| !a.is_hide_set()) {
581	        completions.retain(|a| !a.is_hide_set());
582	    }
583	    let mut seen_ids = HashSet::new();
584	    completions.retain(move |a| {
585	        if let Some(id) = a.get_id().cloned() {
586	            seen_ids.insert(id)
587	        } else {
588	            true
589	        }
590	    });
591	
592	    let mut tags = Vec::new();
593	    for candidate in &completions {
594	        let tag = candidate.get_tag().cloned();
595	        if !tags.contains(&tag) {
596	            tags.push(tag);
597	        }
598	    }
599	    completions.sort_by_key(|c| {
600	        (
601	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
602	            c.get_display_order(),
603	        )
604	    });
605	
606	    Ok(completions)
607	}
