609	/// Generate value candidates for the segment under the cursor of a
610	/// delimiter-separated multi-value option.
611	///
612	/// `prior_segments` is the number of segments already closed by earlier shell
613	/// words; `prior_used` are their literal values, suppressed from the result so
614	/// an already selected value is not offered a second time.  Candidates cover
615	/// only the current shell word, so `prefix` from closed segments is limited to
616	/// the current word as well.
617	///
618	/// `Ok` carries the candidates; `Err(())` marks an illegal segment position
619	/// (an empty segment or a segment past the accepted number of values).
620	fn complete_segment_value(
621	    value: &OsStr,
622	    opt: &clap::Arg,
623	    prior_segments: usize,
624	    prior_used: &[&OsStr],
625	    arg_index: usize,
626	    current_dir: Option<&std::path::Path>,
627	) -> Result<Vec<CompletionCandidate>, ()> {
628	    let Some(cursor) = cursor_delimited(opt, value, prior_segments)? else {
629	        // Not a bounded delimiter option: keep the legacy whole-word
630	        // completion (its own `rsplit_delimiter` handles single-value args).
631	        return Ok(complete_arg_value(
632	            value.to_str().ok_or(value),
633	            opt,
634	            current_dir,
635	            arg_index,
636	        ));
637	    };
638	
639	    let mut used: Vec<&OsStr> = prior_used.to_vec();
640	    used.extend(cursor.closed.iter().copied());
641	
642	    let mut values = complete_arg_value(
643	        Ok(cursor.current.to_str().ok_or(())?),
644	        opt,
645	        current_dir,
646	        arg_index,
647	    );
648	    // An already closed segment stays selected and must not reappear.
649	    values.retain(|comp| !used.iter().any(|u| *u == comp.get_value()));
650	    if !cursor.prefix.is_empty() {
651	        values = values
652	            .into_iter()
653	            .map(|comp| comp.add_prefix(cursor.prefix))
654	            .collect();
655	    }
656	    Ok(values)
657	}
