659	/// Completion at a space-separated option value word tracked by `state`.
660	fn complete_separate_opt_value(
661	    value: Result<&str, &OsStr>,
662	    state: &OptState<'_>,
663	    current_dir: Option<&std::path::Path>,
664	) -> Result<Vec<CompletionCandidate>, ()> {
665	    let value_os = match value {
666	        Ok(value) => OsStr::new(value),
667	        Err(value_os) => value_os,
668	    };
669	    let used: Vec<&OsStr> = state.used.iter().map(OsString::as_os_str).collect();
670	    complete_segment_value(
671	        value_os,
672	        state.opt,
673	        state.used.len(),
674	        &used,
675	        state.word.saturating_sub(1),
676	        current_dir,
677	    )
678	}
