680	/// Complete the inline value carried by the cursor's option word.
681	///
682	/// This covers `--name=value` as well as short clusters with an attached
683	/// value, e.g. `-ovalue` and `-o=value` (including leading flags, `-abovalue`).
684	/// It returns the option's value candidates, re-prefixed with the exact
685	/// option spelling, when the cursor is inside such a value.  The whole word is
686	/// consumed by its option: nothing after `=` or past the taking flag takes
687	/// part in option-name, subcommand or positional completion, and the word is
688	/// not yet part of the conflict set.
689	///
690	/// A bare `--name`/`-o` whose value is still a separate word completes
691	/// normally, as does an unknown long name, a recognized option that takes no
692	/// value and anything else that cannot be recognized: `None` preserves the
693	/// existing failure semantics rather than guessing a split.
694	///
695	/// `Some(Err(()))` means the recognized word is an illegal value position for
696	/// a bounded delimiter option (an empty segment or a segment past the accepted
697	/// number of values) and must yield "no completion generated".
698	fn complete_inline_option_value(
699	    arg: &clap_lex::ParsedArg<'_>,
700	    cmd: &clap::Command,
701	    current_dir: Option<&std::path::Path>,
702	    disabled: &HashSet<Id>,
703	) -> Option<Result<Vec<CompletionCandidate>, ()>> {
704	    if let Some((flag, value)) = arg.to_long() {
705	        let flag = flag.ok()?;
706	        // A bare `--name` has no attached value and is completed as an option name.
707	        let value = value?;
708	        let opt = cmd.get_arguments().find(|a| {
709	            a.get_long_and_visible_aliases()
710	                .is_some_and(|longs| longs.into_iter().any(|long| long == flag))
711	        })?;
712	        if !opt.get_num_args().expect("built").takes_values() {
713	            return None;
714	        }
715	        if disabled.contains(opt.get_id()) {
716	            return Some(Ok(Vec::new()));
717	        }
718	        let prefix = format!("--{flag}=");
719	        return Some(
720	            complete_segment_value(value, opt, 0, &[], 0, current_dir).map(|values| {
721	                values
722	                    .into_iter()
723	                    .map(|comp| comp.add_prefix(&prefix))
724	                    .collect()
725	            }),
726	        );
727	    }
728	
729	    let short = arg.to_short()?;
730	    if short.is_negative_number() {
731	        return None;
732	    }
733	    let (leading_flags, opt, mut value_flags, _) = parse_shortflags(cmd, short);
734	    let opt = opt?;
735	
736	    // Detect an attached value: once the cluster reaches its value-taking
737	    // flag, everything left is the value, optionally introduced by `=`.  With
738	    // no remainder and no `=` (`-o`), the word is left to the regular option
739	    // completion, which already offers inline values.
740	    let mut peek = value_flags.clone();
741	    let has_equal = matches!(peek.next_flag(), Some(Ok('=')));
742	    if !has_equal && value_flags.is_empty() {
743	        return None;
744	    }
745	    if has_equal {
746	        // Consume the `=` so the remainder is the bare value (possibly empty
747	        // for `-o=`), matching the space-separated empty-value position.
748	        value_flags.next_flag();
749	    }
750	    if disabled.contains(opt.get_id()) {
751	        return Some(Ok(Vec::new()));
752	    }
753	    let value = value_flags.next_value_os().unwrap_or(OsStr::new(""));
754	    let sep = if has_equal { "=" } else { "" };
755	    let prefix = format!("-{leading_flags}{sep}");
756	    Some(
757	        complete_segment_value(value, opt, 0, &[], 0, current_dir).map(|values| {
758	            values
759	                .into_iter()
760	                .map(|comp| comp.add_prefix(&prefix))
761	                .collect()
762	        }),
763	    )
764	}
