766	fn complete_option(
767	    arg: &clap_lex::ParsedArg<'_>,
768	    cmd: &clap::Command,
769	    current_dir: Option<&std::path::Path>,
770	    disabled: &HashSet<Id>,
771	) -> Vec<CompletionCandidate> {
772	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
773	    let mut completions = Vec::<CompletionCandidate>::new();
774	    if arg.is_empty() {
775	        completions.extend(longs_and_visible_aliases(cmd, disabled));
776	        completions.extend(hidden_longs_aliases(cmd, disabled));
777	
778	        let dash_or_arg = if arg.is_empty() {
779	            "-".into()
780	        } else {
781	            arg.to_value_os().to_string_lossy()
782	        };
783	        completions.extend(
784	            shorts_and_visible_aliases(cmd, disabled)
785	                .into_iter()
786	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
787	        );
788	    } else if arg.is_stdio() {
789	        // HACK: Assuming knowledge of is_stdio
790	        let dash_or_arg = if arg.is_empty() {
791	            "-".into()
792	        } else {
793	            arg.to_value_os().to_string_lossy()
794	        };
795	        completions.extend(
796	            shorts_and_visible_aliases(cmd, disabled)
797	                .into_iter()
798	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
799	        );
800	
801	        completions.extend(longs_and_visible_aliases(cmd, disabled));
802	        completions.extend(hidden_longs_aliases(cmd, disabled));
803	    } else if arg.is_escape() {
804	        // HACK: Assuming knowledge of is_escape
805	        completions.extend(longs_and_visible_aliases(cmd, disabled));
806	        completions.extend(hidden_longs_aliases(cmd, disabled));
807	    } else if let Some((flag, value)) = arg.to_long() {
808	        if let Ok(flag) = flag {
809	            if let Some(value) = value {
810	                let opt = cmd.get_arguments().find(|a| {
811	                    a.get_long_and_visible_aliases()
812	                        .is_some_and(|longs| longs.into_iter().any(|long| long == flag))
813	                });
814	                if let Some(arg) = opt {
815	                    if !disabled.contains(arg.get_id()) {
816	                        if let Ok(values) =
817	                            complete_segment_value(value, arg, 0, &[], 0, current_dir)
818	                        {
819	                            completions.extend(
820	                                values
821	                                    .into_iter()
822	                                    .map(|comp| comp.add_prefix(format!("--{flag}="))),
823	                            );
824	                        }
825	                    }
826	                }
827	            } else {
828	                completions.extend(
829	                    longs_and_visible_aliases(cmd, disabled)
830	                        .into_iter()
831	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
832	                );
833	                completions.extend(
834	                    hidden_longs_aliases(cmd, disabled)
835	                        .into_iter()
836	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
837	                );
838	            }
839	        }
840	    } else if let Some(short) = arg.to_short() {
841	        if !short.is_negative_number() {
842	            // Find the first takes_values option.
843	            let (leading_flags, takes_value_opt, mut short, _) = parse_shortflags(cmd, short);
844	
845	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
846	            if let Some(opt) = takes_value_opt {
847	                if !disabled.contains(opt.get_id()) {
848	                    let mut peek_short = short.clone();
849	                    let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
850	                        short.next_flag();
851	                        true
852	                    } else {
853	                        false
854	                    };
855	
856	                    let value = short.next_value_os().unwrap_or(OsStr::new(""));
857	                    if let Ok(values) = complete_segment_value(value, opt, 0, &[], 0, current_dir) {
858	                        completions.extend(values.into_iter().map(|comp| {
859	                            let sep = if has_equal { "=" } else { "" };
860	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
861	                        }));
862	                    }
863	                }
864	            } else {
865	                completions.extend(
866	                    shorts_and_visible_aliases(cmd, disabled)
867	                        .into_iter()
868	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
869	                );
870	            }
871	        }
872	    }
873	    debug!("complete_option: completions={completions:?}");
874	    completions
875	}
