877	fn complete_arg_value(
878	    value: Result<&str, &OsStr>,
879	    arg: &clap::Arg,
880	    current_dir: Option<&std::path::Path>,
881	    arg_index: usize,
882	) -> Vec<CompletionCandidate> {
883	    let mut values = Vec::new();
884	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
885	
886	    let (prefix, value) =
887	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
888	
889	    let value_os = match value {
890	        Ok(value) => OsStr::new(value),
891	        Err(value_os) => value_os,
892	    };
893	
894	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
895	        values.extend(completer.complete_at(arg_index, value_os));
896	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
897	        values.extend(complete_value_candidates(
898	            value_os,
899	            completer.value_candidates(),
900	        ));
901	    } else if let Some(possible_values) = possible_values(arg) {
902	        if let Ok(value) = value {
903	            values.extend(complete_candidates_str(
904	                value,
905	                possible_value_candidates(possible_values),
906	            ));
907	        }
908	    } else {
909	        match arg.get_value_hint() {
910	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
911	                // Should not complete
912	            }
913	            clap::ValueHint::AnyPath => {
914	                values.extend(complete_path(value_os, current_dir, &|_| true));
915	            }
916	            clap::ValueHint::FilePath => {
917	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
918	            }
919	            clap::ValueHint::DirPath => {
920	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
921	            }
922	            clap::ValueHint::ExecutablePath => {
923	                use is_executable::IsExecutable;
924	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
925	            }
926	            clap::ValueHint::CommandName
927	            | clap::ValueHint::CommandString
928	            | clap::ValueHint::CommandWithArguments
929	            | clap::ValueHint::Username
930	            | clap::ValueHint::Hostname
931	            | clap::ValueHint::Url
932	            | clap::ValueHint::EmailAddress => {
933	                // No completion implementation
934	            }
935	            _ => {
936	                // Safe-ish fallback
937	                values.extend(complete_path(value_os, current_dir, &|_| true));
938	            }
939	        }
940	
941	        values.sort();
942	    }
943	
944	    if let Some(prefix) = prefix {
945	        values = values
946	            .into_iter()
947	            .map(|comp| comp.add_prefix(prefix))
948	            .collect();
949	    }
950	    values = values
951	        .into_iter()
952	        .map(|comp| {
953	            if comp.get_tag().is_some() {
954	                comp
955	            } else {
956	                comp.tag(Some(arg.to_string().into()))
957	            }
958	        })
959	        .collect();
960	
961	    debug!("complete_arg_value: values={values:?}");
962	    values
963	}
