965	fn rsplit_delimiter<'s, 'o>(
966	    value: Result<&'s str, &'o OsStr>,
967	    delimiter: Option<char>,
968	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
969	    let delimiter = delimiter?;
970	    let value = value.ok()?;
971	    let pos = value.rfind(delimiter)?;
972	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
973	    Some((Some(prefix), Ok(value)))
974	}
