1006	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
1007	    debug!(
1008	        "complete_subcommand: cmd={:?}, value={:?}",
1009	        cmd.get_name(),
1010	        value
1011	    );
1012	
1013	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
1014	        .into_iter()
1015	        .filter(|x| x.get_value().starts_with(value))
1016	        .collect();
