1158	/// Parse the short flags and find the first `takes_values` option.
1159	///
1160	/// The returned bool is `true` only when every scanned cluster member was a
1161	/// recognized option. Anything after the first value-taking option is the
1162	/// option's value and therefore not scanned; invalid UTF-8 and unknown short
1163	/// characters make the result `false`.
1164	fn parse_shortflags<'c, 's>(
1165	    cmd: &'c clap::Command,
1166	    mut short: clap_lex::ShortFlags<'s>,
1167	) -> (
1168	    String,
1169	    Option<&'c clap::Arg>,
1170	    clap_lex::ShortFlags<'s>,
1171	    bool,
1172	) {
1173	    let takes_value_opt;
1174	    let mut leading_flags = String::new();
1175	    let mut cluster_valid = true;
1176	    // Find the first takes_values option.
1177	    loop {
1178	        match short.next_flag() {
1179	            Some(Ok(opt)) => {
1180	                leading_flags.push(opt);
1181	                let found = cmd.get_arguments().find(|a| {
1182	                    let shorts = a.get_short_and_visible_aliases();
1183	                    let is_find = shorts.map(|v| {
1184	                        let mut iter = v.into_iter();
1185	                        let c = iter.find(|c| *c == opt);
1186	                        c.is_some()
1187	                    });
1188	                    is_find.unwrap_or(false)
1189	                });
1190	                if let Some(opt) = found {
1191	                    if opt.get_num_args().expect("built").takes_values() {
1192	                        takes_value_opt = Some(opt);
1193	                        break;
1194	                    }
1195	                } else {
1196	                    cluster_valid = false;
1197	                }
1198	            }
1199	            Some(Err(_)) => {
1200	                cluster_valid = false;
1201	                takes_value_opt = None;
1202	                break;
1203	            }
1204	            None => {
1205	                takes_value_opt = None;
1206	                break;
1207	            }
1208	        }
1209	    }
1210	
1211	    (leading_flags, takes_value_opt, short, cluster_valid)
1212	}
1213	
1214	/// Parse the positional arguments. Return the new state and the new positional index.
1215	fn parse_positional<'a>(
1216	    cmd: &clap::Command,
1217	    pos_index: usize,
1218	    is_escaped: bool,
1219	    state: ParseState<'a>,
1220	) -> (ParseState<'a>, usize) {
1221	    let pos_arg = cmd
1222	        .get_positionals()
1223	        .find(|p| p.get_index() == Some(pos_index));
1224	    let num_args = pos_arg
1225	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
1226	        .unwrap_or(1);
1227	
1228	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
1229	        if num_args > 1 {
1230	            (ParseState::Pos((pos_index, 1)), pos_index)
1231	        } else {
1232	            if is_escaped {
1233	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
1234	            } else {
1235	                (ParseState::ValueDone, pos_index + 1)
1236	            }
1237	        }
1238	    };
1239	    match state {
1240	        ParseState::ValueDone => {
1241	            update_state_with_new_positional(pos_index)
1242	        },
1243	        ParseState::Pos((prev_pos_index, num_arg)) => {
1244	            if prev_pos_index == pos_index {
1245	                if num_arg + 1 < num_args {
1246	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
1247	                } else {
1248	                    if is_escaped {
1249	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
1250	                    } else {
1251	                        (ParseState::ValueDone, pos_index + 1)
1252	                    }
1253	                }
1254	            } else {
1255	                update_state_with_new_positional(pos_index)
1256	            }
1257	        }
1258	        ParseState::Opt(..) => unreachable!(
1259	            "This branch won't be hit,
1260	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
1261	        ),
1262	    }
1263	}
1264	
1265	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
1266	    cmd.get_positionals()
1267	        .find(|a| a.get_index() == Some(pos_index))
1268	        .map(|p| p.is_allow_hyphen_values_set())
1269	        .unwrap_or(false)
1270	}
1271	
1272	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
1273	    let val = arg.to_value_os();
1274	    if val.starts_with("-") {
1275	        if let ParseState::Opt(state) = state {
1276	            return state.opt.is_allow_hyphen_values_set();
1277	        }
1278	    }
1279	
1280	    false
1281	}
1282	
1283	/// Arguments that must not be offered because they conflict with an explicitly
1284	/// present option. The present options themselves are never disabled.
1285	fn gather_disabled_args(cmd: &clap::Command, explicit: &HashSet<Id>) -> HashSet<Id> {
1286	    let mut disabled = HashSet::new();
1287	    if explicit.is_empty() {
1288	        return disabled;
1289	    }
1290	    for arg in cmd.get_arguments() {
1291	        if explicit.contains(arg.get_id()) {
1292	            // A present option hides everything it conflicts with ...
1293	            for id in arg_direct_conflicts(cmd, arg) {
1294	                if !explicit.contains(&id) {
1295	                    disabled.insert(id);
1296	                }
1297	            }
1298	        } else {
1299	            // ... and is hidden when either side declares the conflict.
1300	            if arg_direct_conflicts(cmd, arg)
1301	                .iter()
1302	                .any(|id| explicit.contains(id))
1303	            {
1304	                disabled.insert(arg.get_id().clone());
1305	            }
1306	        }
1307	    }
1308	    disabled
1309	}
1310	
1311	/// Conflict partners of `arg`, following the same rules as clap's parser:
1312	/// - the argument's own `conflicts_with` / `conflicts_with_all`
1313	/// - `conflicts_with` / `conflicts_with_all` of every group the argument belongs to
1314	/// - the other members of non-`multiple` groups
1315	///
1316	/// Group ids are expanded to their argument members.
1317	/// `overrides_with` relationships are intentionally not considered.
1318	fn arg_direct_conflicts(cmd: &clap::Command, arg: &clap::Arg) -> HashSet<Id> {
1319	    let mut conflicts = arg
1320	        .get_conflicts_with()
1321	        .map(ToOwned::to_owned)
1322	        .collect::<HashSet<_>>();
1323	    for group in cmd.get_groups() {
1324	        let members = unroll_group(cmd, group.get_id());
1325	        if !members.iter().any(|m| m == arg.get_id()) {
1326	            continue;
1327	        }
1328	        conflicts.extend(group.get_conflicts_with().map(ToOwned::to_owned));
1329	        if !group.is_multiple_set() {
1330	            conflicts.extend(members.into_iter().filter(|m| m != arg.get_id()));
1331	        }
1332	    }
1333	    conflicts
1334	        .iter()
1335	        .flat_map(|id| unroll_group(cmd, id))
1336	        .collect()
1337	}
1338	
1339	/// Resolve an argument or group id to its argument members.
1340	/// Unknown ids resolve to themselves.
1341	fn unroll_group(cmd: &clap::Command, id: &Id) -> Vec<Id> {
1342	    let mut pending = vec![id.clone()];
1343	    let mut args = Vec::new();
1344	    while let Some(id) = pending.pop() {
1345	        if cmd.get_arguments().any(|a| a.get_id() == &id) {
1346	            if !args.contains(&id) {
1347	                args.push(id);
1348	            }
1349	        } else if let Some(group) = cmd.get_groups().find(|g| g.get_id() == &id) {
1350	            pending.extend(group.get_args().map(ToOwned::to_owned));
1351	        } else if !args.contains(&id) {
1352	            args.push(id);
1353	        }
1354	    }
1355	    args
1356	}
