329	    current_dir: Option<&std::path::Path>,
330	    is_wanted: &dyn Fn(&std::path::Path) -> bool,
331	) -> Vec<CompletionCandidate> {
332	    let mut completions = Vec::new();
333	    let mut potential = Vec::new();
334	
335	    let value_path = std::path::Path::new(value_os);
336	    let (prefix, current) = split_file_name(value_path);
337	    let current = current.to_string_lossy();
338	    let search_root = if prefix.is_absolute() {
339	        prefix.to_owned()
340	    } else if prefix.iter().next() == Some(OsStr::new("~")) {
341	        let prefix = prefix.strip_prefix("~").unwrap_or(prefix);
342	        let home_dir = match std::env::home_dir() {
343	            Some(home_dir) => home_dir,
344	            None => {
345	                // Can't complete without a `home_dir`
346	                return completions;
347	            }
348	        };
349	        home_dir.join(prefix)
350	    } else {
351	        let current_dir = match current_dir {
352	            Some(current_dir) => current_dir,
353	            None => {
354	                // Can't complete without a `current_dir`
355	                return completions;
356	            }
357	        };
358	        current_dir.join(prefix)
359	    };
360	    debug!("complete_path: search_root={search_root:?}, prefix={prefix:?}");
361	
362	    if value_os.is_empty() && is_wanted(&search_root) {
363	        completions.push(".".into());
364	    }
365	
366	    for entry in std::fs::read_dir(&search_root)
367	        .ok()
368	        .into_iter()
369	        .flatten()
370	        .filter_map(Result::ok)
371	    {
372	        let raw_file_name = entry.file_name();
373	        if !raw_file_name.starts_with(&current) {
374	            continue;
375	        }
376	
377	        if entry.path().is_dir() {
378	            let mut suggestion = prefix.join(&raw_file_name);
379	            suggestion.push(""); // Ensure trailing `/`
380	            let candidate = CompletionCandidate::new(suggestion.as_os_str().to_owned())
381	                .hide(is_hidden(&raw_file_name));
382	
383	            if is_wanted(&entry.path()) {
384	                completions.push(candidate);
385	            } else {
386	                potential.push(candidate);
387	            }
388	        } else {
389	            if is_wanted(&entry.path()) {
390	                let suggestion = prefix.join(&raw_file_name);
391	                let candidate = CompletionCandidate::new(suggestion.as_os_str().to_owned())
392	                    .hide(is_hidden(&raw_file_name));
393	                completions.push(candidate);
394	            }
395	        }
396	    }
397	    completions.sort();
398	    potential.sort();
399	    completions.extend(potential);
400	
401	    completions
402	}
